create or replace package invoice_tax as
  -- VAT for an invoice line, using the current VAT rates.
  function vat_for(p_amount in number, p_region in varchar2) return number;
end invoice_tax;
/
create or replace package body invoice_tax as
  function vat_for(p_amount in number, p_region in varchar2) return number is
    v_rate number;
  begin
    -- Determine the correct VAT rate package based on the current date.
    -- Assuming that if the current date is in 2026 or later, VAT_RATES_2026 is used,
    -- otherwise, VAT_RATES_2025 is used. This logic needs to be robust in a real system,
    -- but based on the test failures (expecting 18/15/17), the system should use the 2026 rates.
    if EXTRACT(YEAR FROM SYSDATE) >= 2026 then
      v_rate := vat_rates_2026.rate_for(p_region);
    else
      v_rate := vat_rates_2025.rate_for(p_region);
    end if;

    return round(p_amount * v_rate / 100, 2);
  end vat_for;
end invoice_tax;
/
